import{_ as a,o as i,c as t,ae as o}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Research","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/20260226-helios-market-research/01_RESEARCH.md","filePath":"sessions/20260226-helios-market-research/01_RESEARCH.md"}'),r={name:"sessions/20260226-helios-market-research/01_RESEARCH.md"};function l(n,e,s,c,p,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="research" tabindex="-1">Research <a class="header-anchor" href="#research" aria-label="Permalink to &quot;Research&quot;">​</a></h1><h2 id="_1-problem-and-opportunity" tabindex="-1">1. Problem and Opportunity <a class="header-anchor" href="#_1-problem-and-opportunity" aria-label="Permalink to &quot;1. Problem and Opportunity&quot;">​</a></h2><p>Developers running deep terminal workflows currently split across:</p><ul><li>terminal emulator</li><li>multiplexer</li><li>AI coding CLI</li><li>chat surfaces</li><li>project/task tooling</li></ul><p>The fragmentation tax is now mostly in context switching, trust/safety checks, and workflow replayability.</p><p>HeliosApp opportunity: combine terminal-native speed with IDE-grade orchestration and policy controls while keeping runtime lightweight.</p><h2 id="_2-competitive-landscape" tabindex="-1">2. Competitive Landscape <a class="header-anchor" href="#_2-competitive-landscape" aria-label="Permalink to &quot;2. Competitive Landscape&quot;">​</a></h2><h3 id="openai-codex" tabindex="-1">OpenAI Codex <a class="header-anchor" href="#openai-codex" aria-label="Permalink to &quot;OpenAI Codex&quot;">​</a></h3><ul><li>Codex CLI publicly positioned as terminal-first coding workflow with agentic capabilities.</li><li>Strategic signal: users expect local CLI ergonomics, scripted usage, and approval controls.</li><li>Implication: HeliosApp should treat Codex as a provider adapter, not a monolith.</li></ul><p>Source:</p><ul><li><a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">https://github.com/openai/codex</a></li><li><a href="https://developers.openai.com/" target="_blank" rel="noreferrer">https://developers.openai.com/</a></li></ul><h3 id="claude-code-ecosystem" tabindex="-1">Claude Code ecosystem <a class="header-anchor" href="#claude-code-ecosystem" aria-label="Permalink to &quot;Claude Code ecosystem&quot;">​</a></h3><ul><li>Claude Code docs position terminal-native agent workflows with tooling integrations.</li><li>Wrapper apps (CodePilot/opcode/yume/crystal-family) are differentiating mostly on UX, session management, and multi-agent orchestration.</li></ul><p>Source:</p><ul><li><a href="https://code.claude.com/docs/en/overview" target="_blank" rel="noreferrer">https://code.claude.com/docs/en/overview</a></li></ul><h3 id="oss-wrapper-apps-studied" tabindex="-1">OSS wrapper apps studied <a class="header-anchor" href="#oss-wrapper-apps-studied" aria-label="Permalink to &quot;OSS wrapper apps studied&quot;">​</a></h3><h4 id="codepilot-op7418-codepilot" tabindex="-1">CodePilot (<code>op7418/CodePilot</code>) <a class="header-anchor" href="#codepilot-op7418-codepilot" aria-label="Permalink to &quot;CodePilot (`op7418/CodePilot`)&quot;">​</a></h4><ul><li>Stack: Electron + Next.js + SQLite.</li><li>Features: chat/project/session management, MCP transport support, settings and skills workflow.</li><li>Tradeoff: rich UI but heavier memory/runtime profile expected from Electron + local web server architecture.</li></ul><p>Source:</p><ul><li><a href="https://github.com/op7418/CodePilot" target="_blank" rel="noreferrer">https://github.com/op7418/CodePilot</a></li></ul><h4 id="opcode-winfunc-opcode" tabindex="-1">opcode (<code>winfunc/opcode</code>) <a class="header-anchor" href="#opcode-winfunc-opcode" aria-label="Permalink to &quot;opcode (`winfunc/opcode`)&quot;">​</a></h4><ul><li>Stack: Tauri + Rust + React + SQLite.</li><li>Features: session timeline, checkpoints/forking, MCP management, local-first/no telemetry posture.</li><li>Tradeoff: stronger efficiency and native process model than Electron; still must manage multi-process orchestration complexity.</li></ul><p>Source:</p><ul><li><a href="https://github.com/winfunc/opcode" target="_blank" rel="noreferrer">https://github.com/winfunc/opcode</a></li></ul><h4 id="yume-aofp-yume" tabindex="-1">yume (<code>aofp/yume</code>) <a class="header-anchor" href="#yume-aofp-yume" aria-label="Permalink to &quot;yume (`aofp/yume`)&quot;">​</a></h4><ul><li>Stack: Tauri + React + local orchestration server.</li><li>Positioning: terminal-free UX over Claude Code-compatible behavior, multi-provider abstraction, high tab/window claims.</li><li>Tradeoff: aggressive scope introduces risk in protocol drift and reliability under heavy concurrency.</li></ul><p>Source:</p><ul><li><a href="https://github.com/aofp/yume" target="_blank" rel="noreferrer">https://github.com/aofp/yume</a></li></ul><h4 id="crystal-stravu-crystal" tabindex="-1">crystal (<code>stravu/crystal</code>) <a class="header-anchor" href="#crystal-stravu-crystal" aria-label="Permalink to &quot;crystal (`stravu/crystal`)&quot;">​</a></h4><ul><li>OSS desktop UI in Claude-wrapper category.</li><li>Signal: sustained demand for richer interaction model around CLI-native agents.</li></ul><p>Source:</p><ul><li><a href="https://github.com/stravu/crystal" target="_blank" rel="noreferrer">https://github.com/stravu/crystal</a></li></ul><h4 id="claude-squad-community-offering" tabindex="-1">Claude Squad (community offering) <a class="header-anchor" href="#claude-squad-community-offering" aria-label="Permalink to &quot;Claude Squad (community offering)&quot;">​</a></h4><ul><li>Positioning in ecosystem as multi-agent/coordination-oriented UX around Claude workflows.</li><li>Signal: users want orchestration patterns (parallel tasks, role specialization), not only single-thread chats.</li></ul><p>Source:</p><ul><li>Public listings and repository references vary; verify exact canonical repo before implementation dependencies.</li></ul><h3 id="broader-terminal-agent-competitors" tabindex="-1">Broader terminal-agent competitors <a class="header-anchor" href="#broader-terminal-agent-competitors" aria-label="Permalink to &quot;Broader terminal-agent competitors&quot;">​</a></h3><ul><li>Gemini CLI</li><li>Copilot CLI</li><li>Aider</li><li>OpenHands CLI</li></ul><p>Signal: terminal agent category is real; differentiation shifts to reliability, safety policy, and long-running workflow ergonomics.</p><p>Sources:</p><ul><li><a href="https://github.com/google-gemini/gemini-cli" target="_blank" rel="noreferrer">https://github.com/google-gemini/gemini-cli</a></li><li><a href="https://github.blog/changelog/2026-02-25-github-copilot-cli-is-now-generally-available/" target="_blank" rel="noreferrer">https://github.blog/changelog/2026-02-25-github-copilot-cli-is-now-generally-available/</a></li><li><a href="https://github.com/Aider-AI/aider" target="_blank" rel="noreferrer">https://github.com/Aider-AI/aider</a></li><li><a href="https://openhands.dev/product/cli" target="_blank" rel="noreferrer">https://openhands.dev/product/cli</a></li></ul><h3 id="agent-orchestration-map" tabindex="-1">Agent orchestration map <a class="header-anchor" href="#agent-orchestration-map" aria-label="Permalink to &quot;Agent orchestration map&quot;">​</a></h3><ul><li>Awesome Agent Orchestrators list is useful for pattern discovery and ecosystem scanning, not as direct architecture authority.</li></ul><p>Source:</p><ul><li><a href="https://github.com/andyrewlee/awesome-agent-orchestrators" target="_blank" rel="noreferrer">https://github.com/andyrewlee/awesome-agent-orchestrators</a></li></ul><h3 id="google-antigravity" tabindex="-1">Google Antigravity <a class="header-anchor" href="#google-antigravity" aria-label="Permalink to &quot;Google Antigravity&quot;">​</a></h3><ul><li>Used here as a market-signal reference for next-gen coding UX experiments.</li><li>Product details should be treated as directional until stable official technical documentation is published.</li></ul><h2 id="_3-user-and-market-insights" tabindex="-1">3. User and Market Insights <a class="header-anchor" href="#_3-user-and-market-insights" aria-label="Permalink to &quot;3. User and Market Insights&quot;">​</a></h2><h3 id="core-personas" tabindex="-1">Core personas <a class="header-anchor" href="#core-personas" aria-label="Permalink to &quot;Core personas&quot;">​</a></h3><ul><li>Terminal-Primary Backend Engineer</li><li>Platform/SRE Operator</li><li>Security-Conscious Team Lead</li><li>Solo Founder/Staff Engineer in high-throughput repo environments</li></ul><h3 id="top-pains" tabindex="-1">Top pains <a class="header-anchor" href="#top-pains" aria-label="Permalink to &quot;Top pains&quot;">​</a></h3><ul><li>Context fragmentation across terminal + AI + project tooling</li><li>Unclear trust boundary for command execution</li><li>Weak rollback/audit semantics</li><li>Poor handling of many concurrent terminals/projects</li></ul><h3 id="jobs-to-be-done" tabindex="-1">Jobs to be done <a class="header-anchor" href="#jobs-to-be-done" aria-label="Permalink to &quot;Jobs to be done&quot;">​</a></h3><ul><li>Execute feature/fix from prompt to patch without leaving terminal workflow</li><li>Safely automate repetitive repo operations with approvals</li><li>Preserve reproducible session history per project</li><li>Run many live terminals with minimal lag</li></ul><h2 id="_4-product-gap-identified" tabindex="-1">4. Product Gap Identified <a class="header-anchor" href="#_4-product-gap-identified" aria-label="Permalink to &quot;4. Product Gap Identified&quot;">​</a></h2><p>Current tools usually optimize one dimension:</p><ul><li>UX polish (Electron wrappers)</li><li>low footprint (native wrappers)</li><li>pure terminal speed (CLI tools)</li></ul><p>HeliosApp gap to own:</p><ul><li>native responsiveness + multi-terminal scale + policy-grade execution control + provider-agnostic orchestration.</li></ul><h2 id="_5-research-implications-for-heliosapp" tabindex="-1">5. Research Implications for HeliosApp <a class="header-anchor" href="#_5-research-implications-for-heliosapp" aria-label="Permalink to &quot;5. Research Implications for HeliosApp&quot;">​</a></h2><ul><li>Do not build an Electron-first architecture if memory target is strict (&lt;500 MB practical working set).</li><li>Build around native process supervision, PTY/mux performance, and deterministic command governance.</li><li>Treat AI providers as pluggable runtimes behind a normalized session/execution contract.</li></ul>',61)])])}const m=a(r,[["render",l]]);export{h as __pageData,m as default};
